using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// Build the chat client through the MEAI abstraction layer.
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// Instantiate the tools the agent can call.
var researchTools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Use the web_search tool multiple times with different queries to gather information.
        2. Use the save_note tool to record key findings as you go.
        3. After gathering enough information (at least 3 searches), use get_notes to
           review everything you've collected and produce a concise summary.
        4. Present the final summary to the user with key findings and sources.
        Be thorough but concise. Always cite where information came from.
        """,
    tools: [
        AIFunctionFactory.Create(researchTools.WebSearch),
        AIFunctionFactory.Create(researchTools.SaveNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]);

agent.ChatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
};

// Prompt the user for a research topic.
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent.
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

AgentResponse response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("─── Research Summary ───\n");
Console.WriteLine(response.Text);

// -----------------------------------------------------------------
// Tool implementations
// -----------------------------------------------------------------

/// <summary>Provides web search and note-taking tools for the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=3&format=json";

            var json = await _httpClient.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}\n");

            foreach (var result in results.EnumerateArray())
            {
                var title = result.GetProperty("title").GetString();
                var snippet = result.GetProperty("snippet").GetString();
                // Strip HTML tags from the snippet.
                snippet = System.Text.RegularExpressions.Regex.Replace(snippet ?? "", "<.*?>", "");
                sb.AppendLine($"- {title}: {snippet}");
                sb.AppendLine($"  Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save an important finding or note during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        Console.WriteLine($"  📝 Note saved: {note[..Math.Min(note.Length, 60)]}...");
        _notes.Add(note);
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"All research notes ({_notes.Count} total):\n");
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

